bicep:
// ---------------------------------------------------------------------------
// main.bicep — generated by azx (App Intent Service · POC #1, dry-run engine)
// DRY-RUN PREVIEW ONLY — review before deploying. azx made no Azure calls.
// Resolved region: eastus2
// Estimated cost: ~$170/mo USD
// ---------------------------------------------------------------------------

targetScope = 'resourceGroup'

@description('Azure region for all resources.')
param location string = 'eastus2'

// Consumption plan — you pay only for running container replicas.
resource appEnv 'Microsoft.App/managedEnvironments@2024-03-01' = {
  name: 'cae-vector-search-api'
  location: location
  properties: {}
}

// Fallback options considered: Azure App Service (always-on web apps) or Azure Static Web Apps (static/JAMstack).
resource web 'Microsoft.App/containerApps@2024-03-01' = {
  name: 'ca-vector-search-api'
  location: location
  properties: {
    managedEnvironmentId: appEnv.id
    configuration: {
      ingress: {
        external: true
        targetPort: 3000
      }
    }
    template: {
      scale: {
        minReplicas: 1
        maxReplicas: 10
      }
    }
  }
  dependsOn: [
    appEnv
    openai
    postgres
  ]
}

// GeneralPurpose tier.
// pgvector extension enabled — vector search is served in-database.
resource postgres 'Microsoft.DBforPostgreSQL/flexibleServers@2024-08-01' = {
  name: 'psql-vector-search-api'
  location: location
  sku: {
    name: 'Standard_D2s_v3'
    tier: 'GeneralPurpose'
  }
  // pgvector: also add a flexibleServers/configurations resource setting azure.extensions = 'VECTOR'.
  properties: {
      version: '16'
      storage: {
        storageSizeGB: 32
      }
      authConfig: {
        passwordAuth: 'Enabled'
      }
  }
}

resource postgresDb 'Microsoft.DBforPostgreSQL/flexibleServers/databases@2024-08-01' = {
  name: 'psql-vector-search-api/appdb'
  properties: {
    charset: 'UTF8'
    collation: 'en_US.utf8'
  }
  dependsOn: [
    postgres
  ]
}

// Token usage is billed per-1K tokens; the fixed cost is $0. Confirm model availability in the chosen region.
resource openai 'Microsoft.CognitiveServices/accounts@2024-10-01' = {
  name: 'oai-vector-search-api'
  location: location
  kind: 'OpenAI'
  sku: {
    name: 'S0'
  }
  properties: {
    publicNetworkAccess: 'Enabled'
    customSubDomainName: name
  }
}

resource openaiDeployTextEmbedding3Large 'Microsoft.CognitiveServices/accounts/deployments@2024-10-01' = {
  name: 'oai-vector-search-api/text-embedding-3-large'
  sku: {
    name: 'Standard'
    capacity: 30
  }
  properties: {
    model: {
      format: 'OpenAI'
      name: 'text-embedding-3-large'
    }
  }
  dependsOn: [
    openai
  ]
}

output webAppName string = web.name
output postgresServerName string = postgres.name
